class Solution { public:int peopleAwareOfSecret(int n,int delay,int forget){const long long mod=1000000007;vector<long long> learn(n+1);learn[1]=1;long long sharing=0;for(int day=2;day<=n;++day){if(day-delay>=1)sharing=(sharing+learn[day-delay])%mod;if(day-forget>=1)sharing=(sharing-learn[day-forget]+mod)%mod;learn[day]=sharing;}long long answer=0;for(int day=max(1,n-forget+1);day<=n;++day)answer=(answer+learn[day])%mod;return answer;} };
